using System;using System.Globalization;using ForteMove.Models.Fleet;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin{public partial class FleetDetails:AdminPage{protected void Page_Load(object sender,EventArgs e){if(IsPostBack)return;long id;if(!long.TryParse(Request.QueryString["id"],out id)){Response.Redirect(ResolveUrl("~/Admin/FleetList.aspx"),true);return;}BusDetails b=ServiceFactory.CreateBusService().GetBusDetails(id);if(b==null){Response.Redirect(ResolveUrl("~/Admin/FleetList.aspx"),true);return;}FlashMessage m=FlashMessageStore.Take(Session);if(m!=null){litFlash.Text=Server.HtmlEncode(m.Text);pnlFlash.Visible=true;}litFleetNumber.Text=Server.HtmlEncode(b.FleetNumber);litVehicle.Text=Server.HtmlEncode(b.Make+" "+b.Model);litRegistration.Text=Server.HtmlEncode(b.RegistrationNumber);litVin.Text=Server.HtmlEncode(b.Vin);litCategory.Text=Server.HtmlEncode(b.CategoryName);litCapacity.Text=b.PassengerCapacity.ToString(CultureInfo.CurrentCulture)+" passengers";litGvm.Text=b.GrossVehicleMassKg.HasValue?b.GrossVehicleMassKg.Value.ToString("N0",CultureInfo.CurrentCulture)+" kg":"GVM required";litLicenceClass.Text=Server.HtmlEncode(b.RequiredLicenceCode??"Pending GVM");litStatus.Text=Server.HtmlEncode(FormatState(b.BaseOperationalState));litCompliance.Text=string.Format(CultureInfo.CurrentCulture,"Licence {0:d}; roadworthy {1:d}; insurance {2:d}",b.LicenceExpiryDate,b.RoadworthyExpiryDate,b.InsuranceExpiryDate);lnkMaintenance.NavigateUrl="~/Admin/Maintenance/ServiceHistory.aspx?id="+id;lnkEdit.NavigateUrl="~/Admin/EditBus.aspx?id="+id;}private static string FormatState(BusOperationalState s){return s==BusOperationalState.OutOfService?"Out of service":s==BusOperationalState.UnderMaintenance?"Under maintenance":s.ToString();}}}
